import type { SVGProps } from 'react';

export type IconWeight = 'duotone' | 'regular' | 'fill';
export type IconProps = Omit<SVGProps<SVGSVGElement>, 'ref'> & { size?: number | string; weight?: IconWeight };

/**
 * По умолчанию ровное начертание: объёмное duotone на 14-18 пикселях
 * размывается — светлая подложка съедает контраст. Объёмное включается
 * точечно, у крупных знаков, через weight="duotone".
 */
const DEFAULT_WEIGHT: IconWeight = 'regular';

function make(shapes: Partial<Record<IconWeight, string>>, name: string) {
  const Icon = ({ size = 16, weight, ...rest }: IconProps) => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width={size} height={size}
      fill="currentColor" role="img" aria-hidden="true" focusable="false" {...rest}
      dangerouslySetInnerHTML={{ __html: shapes[weight ?? DEFAULT_WEIGHT] ?? shapes.regular! }} />
  );
  Icon.displayName = name;
  return Icon;
}

